INSERT INTO `ayuda_tickets` (`id`, `id_usuario`, `titulo`, `descripcion`, `fotos`, `estado`, `fecha_registro`) VALUES
(4, 10, 'No tengo botón de edición en Cuentas x Pagar', 'Si me equivoco, no tengo opción de reversar el error, o agregar mas contenido al registro...', 'ticket_1790190911_908_1.jpg', 'Corregido', '2026-09-23 15:15:11'),
(5, 10, 'Al hacer click en los productos nuevos...', 'Al hacer click en la imagen de los productos nuevos recientemente registrados: No carga en la cotización: Pantalón tipo \"Carpenter\" y \"Camisa lava y listo\"', 'ticket_1790193459_458_1.jpg', 'Corregido', '2026-09-23 15:57:39'),
(6, 10, 'No aparece el tipo de tela...', 'Debe aparecer cuando se selecciona el producto el tipo de tela para cotizar.\r\nNo aparece ahora en el seleccionador, y por defecto en la cotización...', 'ticket_1790346473_502_1.jpg,ticket_1790346473_263_2.jpg', 'Corregido', '2026-09-25 10:27:53'),
(7, 10, 'No abren los botones de Categorías...', 'No abren los botones al hacer click en el botón de categoría\r\nNo puedo adjuntar un clip de video para que puedas visualizar en este módulo', 'ticket_1790351934_980_1.mp4', 'Corregido', '2026-09-25 11:58:54'),
(8, 10, 'Se puede cambiar el vendedor?', 'Estos clientes son de Willian Sulabarán, pero yo coticé con mi módulo sin darme cuenta. \r\n(Error de usuario)', 'ticket_1790354268_909_1.jpg', 'Corregido', '2026-09-25 12:37:48'),
(9, 11, 'No es lo que he vendido realmente...', 'Mis ventas este mes ha superado la meta...', 'ticket_1790365541_582_1.jpg', 'Corregido', '2026-09-25 15:45:41'),
(10, 10, 'Alineación desordenada...', 'Hola José, alinea por favor a la izquierda todo, esa vista es la presentación de la cotización modo Licitación, coloqué unas imágenes pero no salieron en el PDF', 'ticket_1790620162_907_1.jpg', 'Corregido', '2026-09-28 14:29:22'),
(11, 11, 'NO ME CARGA LAS TALLAS S', 'EL SISTEMA NO ME CARGA LAS TALLA S EN LA ORDEN DE ORINOKIA Y TUVE QUE PONERLAS TALLAS XS... POR FAVOR CORREGIR EL DETALLE PORQUE LAS TALLA REALES SON S DE DAMAS', '', 'Corregido', '2026-10-05 15:11:43'),
(12, 11, 'CAMBIO DE STATUS', 'LA COTIZACION 0139 DE BEVERLY COLMENARES NO DEBE DINERO, SIN EMBARGO SE MANTIENE CON EL SATUS DE PAGO INICIAL... POR FAVOR CORREGIR', '', 'Corregido', '2026-10-06 18:11:42'),
(13, 10, 'Necesito pasar esto a confección', 'Necesito pasar esto a confección como muestra Fisica', 'ticket_1791328077_898_1.jpg', 'Corregido', '2026-10-06 19:07:57');
